def play_recursively_combat(p1: list, p2: list) -> bool:
    rounds = set()
    winner = None
    while len(p1) > 0 and len(p2) > 0:
        r = tuple(p1 + [-1] + p2)
        if r in rounds:
            return True
        else:
            rounds.add(r)

        c1 = p1.pop(0)
        c2 = p2.pop(0)

        if c1 <= len(p1) and c2 <= len(p2):
            winner = play_recursively_combat(p1[:c1], p2[:c2])
        else:
            winner = c1 > c2

        if winner:
            p1.append(c1)
            p1.append(c2)
        else:
            p2.append(c2)
            p2.append(c1)

    return winner


