    for kw in ('算', '别', '不', '停', '取消'):
        if kw in sentence:
            # a keyword matches
            break
    else:
        # no keyword matches
        return False

    if re.match(r'^那?[算别不停]\w{0,3}了?吧?$', sentence) or \
            re.match(r'^那?(?:[给帮]我)?取消了?吧?$', sentence):
