class Solution:
    def insertionSortList(self, head):
        dumm = head
        while head:
            val, head, prev = head.val, head.next, dumm
            while val >= prev.val:
                prev = prev.next
            while prev != head:
                prev.val, prev, val = val, prev.next, prev.val
        return dumm


