def confirm_or_exit(prompt):
  options = ['y','n','q']
  option_prompt = '/'.join(options)

  choice = None
  while choice not in options:
    choice = raw_input("%s (%s): " % (prompt, option_prompt)).lower()

  if choice == 'y':
    return True
  if choice == 'n':
    return False
  if choice == 'q':
    raise SystemExit(0)


