        return self.node_factory.create_node_list(self.manditory,
                                                  self.optional)


class TimedSystem(System):

    def is_timed_out(self, lt, ct, timeout):
        if lt is None:
            return False
        return ct - lt > timeout

    def process(self):
        t = time.time()
        for node in self.get_nodes():
            self.handle(node, t)
            self.clean(node)

