def findModule(module):
    from imp import find_module
    if '.' not in module:
        return find_module(module)[1]
    else:
        parent,child = module.rsplit('.', 1)
        #mparent = loadModule(parent)
        pparent = findModule(parent)
        pchild = find_module(child, [pparent])[1]
        return pchild

