def pick(filename, keys = []):
    import pickle
    try:
        f = open(filename)
        v = pickle.load(f)
        if keys:
            try:
                for k in keys:
                    v = v[k]
            except:
                traceback.print_exc()
        return v
    except:
        traceback.print_exc()
    finally:
        f.close()

def dump(value, filename, as_dict = False):
    import pickle
    try:
        f = open(filename, 'w')
        if not as_dict:
            try:
                pickle.dump(value, f)
            except:
                as_dict = True
        if as_dict:
            pickle.dump(obj2dict(value), f)
    except:
        traceback.print_exc()
    finally:
        f.close()

